mapper.select:
SELECT MAX(PWF.PA_CONFIRM_FLAG)
  FROM PA_WORK_FLOW PWF
 WHERE PWF.PAY_SCHEDULE_NO = #{payScheduleNo, jdbcType=VARCHAR}

SELECT ASM.AR_SUMMARY_MANAGE_NO, HRE.LOCAL_NAME, HRE.EMPID, GET_DEPT_NAME(HRE.DEPTNO, #{lang, jdbcType=VARCHAR}) AS DEPTNAME, GET_GLOBAL_NAME(HRE.POST_GRADE_NO, #{lang, jdbcType=VARCHAR}) AS POST_GRADE, TO_CHAR(HRE.DATE_STARTED, 'DD/MM/YYYY') AS DATE_STARTED, GET_GLOBAL_NAME(ASM.ITEM_NO, #{lang, jdbcType=VARCHAR}) AS ITEM_NAME, TO_CHAR(PPS.AR_START_DATE, 'DD/MM/YYYY') AS AR_START_DATE, ASM.CAL_VALUE, ASM.FINAL_VALUE, ASM.REMARK, GET_EMP_LOCAL_NAME(ASM.UPDATED_BY, #{cpnyId, jdbcType=VARCHAR}) || ' ' || ASM.UPDATED_IP AS UPDATED_BY, TO_CHAR(ASM.UPDATE_DATE, 'DD/MM/YYYY HH24:MI') AS UPDATE_DATE FROM AR_SUMMARY_MANAGE_HTSV ASM, HR_EMPLOYEE HRE, PA_PAY_SCHEDULE PPS WHERE ASM.PERSON_ID = HRE.PERSON_ID AND ASM.PAY_SCHEDULE_NO = PPS.PAY_SCHEDULE_NO AND PPS.CPNY_ID = #{cpnyId, jdbcType=VARCHAR} AND ASM.PAY_SCHEDULE_NO = #{payScheduleNo, jdbcType=VARCHAR}
AND ASM.ITEM_NO IN
#{itemNo, jdbcType=VARCHAR}
AND ASM.FINAL_VALUE IS NOT NULL
ORDER BY HRE.EMPID, ASM.AR_SUMMARY_MANAGE_NO

mapper.update:
UPDATE AR_SUMMARY_MANAGE_HTSV
   SET FINAL_VALUE = #{item.finalValue, jdbcType=NUMERIC},
       REMARK      = #{item.remark, jdbcType=VARCHAR},
       UPDATE_DATE = SYSDATE,
       UPDATED_BY  = #{adminID, jdbcType=VARCHAR},
       UPDATED_IP  = #{adminIP, jdbcType=VARCHAR}
 WHERE AR_SUMMARY_MANAGE_NO = #{item.arSummaryManageNo, jdbcType=NUMERIC}
   AND PAY_SCHEDULE_NO      = #{payScheduleNo, jdbcType=VARCHAR}
